 function safeMarkdown(value){
  const source=esc(value||'').replace(/\r/g,'');
  const inline=text=>text.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
  const lines=source.split('\n'),out=[];let list='';
  const closeList=()=>{if(list){out.push(`</${list}>`);list='';}};
  for(const raw of lines){
   const line=raw.trim(),unordered=line.match(/^[-*]\s+(.+)$/),ordered=line.match(/^\d+[.)]\s+(.+)$/);
   if(unordered||ordered){const next=ordered?'ol':'ul';if(list!==next){closeList();out.push(`<${next}>`);list=next;}out.push(`<li>${inline((unordered||ordered)[1])}</li>`);continue;}
   closeList();if(!line)continue;
   const heading=line.match(/^(#{1,3})\s+(.+)$/);if(heading){const level=heading[1].length+1;out.push(`<h${level}>${inline(heading[2])}</h${level}>`);}else out.push(`<p>${inline(line)}</p>`);
  }
  closeList();return out.join('');
 }
 const guideHeadingKey=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 function guideSections(value){
  const sections=[];let current={title:'',body:[]};
  for(const raw of String(value||'').replace(/\r/g,'').split('\n')){const heading=raw.trim().match(/^#{1,3}\s+(.+)$/);if(heading){if(current.title||current.body.some(Boolean))sections.push({...current,body:current.body.join('\n').trim()});current={title:heading[1].trim(),body:[]};}else current.body.push(raw);}
  if(current.title||current.body.some(Boolean))sections.push({...current,body:current.body.join('\n').trim()});return sections;
 }
 function guidePresentation(article){
  const sections=guideSections(article.content),generic=sections.some(section=>guideHeadingKey(section.title)==='disponibilite');
  if(!generic)return`<div class="help-guide-sections">${safeMarkdown(article.content)}</div>`;
  const sectionMap=new Map(sections.map(section=>[guideHeadingKey(section.title),section.body]));
  const get=(...keys)=>keys.map(key=>sectionMap.get(key)).find(Boolean)||'';
  const blocks=[
   ['Comment faire',get('etapes','explication et etapes'),'steps'],
   ['Avant de commencer',get('prerequis et permissions'),'prerequisites'],
   ['Ce que vous devez obtenir',get('resultat attendu'),'result'],
   ['Si quelque chose bloque',get('erreurs et resolution'),'troubleshooting'],
   ['Bon à savoir',[get('cas particuliers'),get('avertissements et limites')].filter(Boolean).join('\n\n'),'tips']
  ].filter(([,body])=>body);
  const intro=get('resume')||article.summary||'';
  return`<div class="help-guide-intro"><span>L’essentiel</span><div>${safeMarkdown(intro)}</div></div><div class="help-guide-sections">${blocks.map(([title,body,kind],index)=>`<section class="help-guide-section ${kind}"><div class="help-guide-section-icon">${kind==='steps'?String(index+1).padStart(2,'0'):kind==='result'?'✓':kind==='troubleshooting'?'!':'•'}</div><div><h2>${esc(title)}</h2>${safeMarkdown(body)}</div></section>`).join('')}</div>`;
 }
