 function piloMessage(message){const sources=message.sources||[];return`<article class="pilo-message ${message.role}"><div class="pilo-avatar">${message.role==='assistant'?'P':'Vous'}</div><div class="pilo-bubble"><p>${piloText(message.content)}</p>${message.detail?`<small>${esc(message.detail)}</small>`:''}${sources.length?`<div class="pilo-sources"><b>Sources officielles</b>${sources.map(source=>`<button onclick="PilozHelp.openArticle('${source.slug}')">${esc(source.title)} →</button>`).join('')}</div>`:''}${message.role==='assistant'&&message.id?`<div class="pilo-feedback"><span>Cette réponse vous aide ?</span><button onclick="PilozHelp.openFeedback('pilo','${message.id}',true)">Oui</button><button onclick="PilozHelp.openFeedback('pilo','${message.id}',false)">Non</button></div>`:''}${message.canCreateTicket?`<button class="help-btn primary compact" onclick="PilozHelp.openTicketFromPilo(${message.isRoadmap?'true':'false'})">${message.isRoadmap?'Proposer cette fonctionnalité':'Créer un ticket'}</button>`:''}</div></article>`;}
