 async function askPilo(form){if(ui.piloBusy)return;const cid=companyId(),question=String(new FormData(form).get('question')||'').trim();if(question.length<2)return;if(ui.piloCompanyId&&ui.piloCompanyId!==cid){ui.piloConversationId=null;ui.piloMessages=ui.piloMessages.slice(0,1);}ui.piloCompanyId=cid;ui.piloMessages.push({role:'user',content:question});form.reset();ui.piloBusy=true;renderPiloSurfaces();try{let result;try{result=await api().invoke('pilo',{action:'ask',companyId:cid,conversationId:ui.piloConversationId,question,safeContext:safeContext()});}catch(edgeError){const sources=await api().rpc('search_piloz_documentation',{search_query:question,target_company_id:cid,safe_context:safeContext(),result_limit:5});if(!sources?.length){const unansweredId=await api().rpc('record_unanswered_pilo_question',{target_company_id:cid,question_text:question,safe_context:safeContext()});result={answer:localPiloAnswer(question),answerLevel:'none',sources:[],unansweredId,canCreateTicket:true};}else result={answer:localPiloAnswer(question,sources),answerLevel:'medium',sources:sources.map(source=>({id:source.article_id,slug:source.slug,title:source.title})),canCreateTicket:false};console.warn('[Pilo] Mode dégradé documenté',{message:edgeError.message});}ui.piloConversationId=result.conversationId||ui.piloConversationId;ui.piloMessages.push({role:'assistant',content:result.answer,detail:result.aiEnabled===false&&result.answerLevel==='medium'?'Réponse de secours basée sur la documentation officielle.':'',sources:result.sources||[],id:result.messageId||'',conversationId:result.conversationId||null,canCreateTicket:!!result.canCreateTicket,isRoadmap:!!result.isRoadmap,question});}catch(error){ui.piloMessages.push({role:'assistant',content:'Pilo est temporairement indisponible. Votre question n’a pas été transformée en faux ticket.',detail:error.message,canCreateTicket:true,question});}finally{ui.piloBusy=false;renderPiloSurfaces();}}
 async function loadTickets(force=false){if(ui.ticketsLoading||ui.ticketsLoaded&&!force)return;ui.ticketsLoading=true;ui.ticketsError='';try{const cid=encodeURIComponent(companyId()),tickets=await api().query('support_ticket_client_view',`select=*&company_id=eq.${cid}&order=updated_at.desc`);ui.tickets=Array.isArray(tickets)?tickets:[];if(ui.ticketId&&!ui.tickets.some(item=>item.id===ui.ticketId))ui.ticketId='';if(ui.ticketId)await loadMessages(ui.ticketId);}catch(error){ui.ticketsError=error.message||'Les tickets n’ont pas pu être chargés.';notify(ui.ticketsError,'error');}finally{ui.ticketsLoaded=true;ui.ticketsLoading=false;if(hash()==='help/tickets')renderCurrent();}}
